#!/usr/bin/env node

const Anthropic = require("@anthropic-ai/sdk");
const https = require("https");

const client = new Anthropic({
  apiKey: process.env.ANTHROPIC_API_KEY,
});

async function handleIssue() {
  const issueNumber = process.env.ISSUE_NUMBER;
  const issueTitle = process.env.ISSUE_TITLE;
  const issueBody = process.env.ISSUE_BODY || "";
  const commentBody = process.env.COMMENT_BODY || "";
  const repo = process.env.REPO;
  const githubToken = process.env.GITHUB_TOKEN;
  const eventName = process.env.EVENT_NAME || "issue";

  console.log(`\n📋 Issue #${issueNumber}: ${issueTitle}`);
  console.log(`📌 Event: ${eventName}`);

  // Determine content to analyze
  const contentToAnalyze = eventName === "issue_comment" ? commentBody : issueBody;

  // Call Claude API
  const message = await client.messages.create({
    model: "claude-opus-4-1",
    max_tokens: 1024,
    messages: [
      {
        role: "user",
        content: `
You are a helpful developer assistant. Analyze this GitHub issue request and provide a concise response or action plan.

Issue #${issueNumber}: ${issueTitle}

Request:
${contentToAnalyze}

Provide:
1. Brief summary
2. Suggested approach / solution
3. Any relevant details or next steps

Format as markdown.
        `,
      },
    ],
  });

  const analysis = message.content[0].text;
  console.log("\n🤖 Claude Analysis:\n", analysis);

  // Post comment on issue
  const responseBody = `## 🤖 Claude Analysis

${analysis}

---
*Analysis generated by Claude AI via GitHub Actions*`;

  const postCommentUrl = `https://api.github.com/repos/${repo}/issues/${issueNumber}/comments`;

  await new Promise((resolve, reject) => {
    const options = {
      hostname: "api.github.com",
      path: `/repos/${repo}/issues/${issueNumber}/comments`,
      method: "POST",
      headers: {
        Authorization: `token ${githubToken}`,
        "User-Agent": "Claude-Issue-Handler",
        Accept: "application/vnd.github.v3+json",
      },
    };

    const req = https.request(options, (res) => {
      let data = "";
      res.on("data", (chunk) => (data += chunk));
      res.on("end", () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log("✅ Comment posted successfully");
          resolve();
        } else {
          reject(new Error(`GitHub API error: ${res.statusCode} ${data}`));
        }
      });
    });

    req.on("error", reject);
    req.write(JSON.stringify({ body: responseBody }));
    req.end();
  });
}

handleIssue().catch((error) => {
  console.error("❌ Error:", error.message);
  process.exit(1);
});
